from __future__ import print_function

import logging
import time
import traceback
from threading import Lock

from ta_ue_plugin_android.uepc.take_care_thread import TakeCareThread, IAbstractTakeCarer
from ta_ue_plugin_android.uepc.ue_manager_exceptions import UeAleadyReservedException
from ta_ue_plugin_android.uepc.ue_manager_exceptions import UeNotReservedException, UeReservationOutOfDate
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra

DEFAULT_FINISH_POOL_TAKE_CARE_THREAD_TIMEOUT = 10
UE_RESERVATION_TIME = 30


class LocksForEachUe(object):
    """LocksForEachUe"""

    def __init__(self):
        """Basic initialization."""
        self._global_lock = Lock()
        self._locks_dict = {}

    def ue_lock(self, ue_sn):
        """
        :param ue_sn:
        :return:
        """
        return self._ensure_lock_exist(ue_sn)

    def _ensure_lock_exist(self, ue_sn):
        with self._global_lock:
            if ue_sn not in self._locks_dict:
                self._locks_dict[ue_sn] = Lock()
        return self._locks_dict[ue_sn]

    def run_if_ue_unlocked(self, ue_sn, to_run, fail_value=None):
        """
        :param ue_sn:
        :param to_run:
        :param fail_value:
        :return:
        """
        lock = self._ensure_lock_exist(ue_sn)
        try:
            if lock.acquire(False):
                print('acquired')
                return to_run()
            print('not acquired')
        finally:
            lock.release()
        return fail_value

    def is_ue_locked(self, ue_sn):
        """
        :param ue_sn:
        :return:
        """
        return self._locks_dict[ue_sn].locked()


class UePool2WithTakeCareThread(IAbstractTakeCarer):
    """UePool2WithTakeCareThread"""
    # pylint: disable=too-many-instance-attributes

    def __init__(self, backend, kill_desktop=True, require_keep_reservation=True):
        """
        :param backend:
        :param kill_desktop:
        :param require_keep_reservation:
        """
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UEPOOL2THREAD'})
        self._backend = backend
        self._take_care_thread = TakeCareThread(self, 5, thread_namesufix="-in-UE-PC")
        self._ues_reserved = {}
        self._ues_reserved_times = {}
        self._thread = None
        self._lock = Lock()
        self._ues_locks = LocksForEachUe()
        self._ues_keep_locks = LocksForEachUe()
        self.thread_sleep_time = UE_RESERVATION_TIME
        self.reservation_timeout = UE_RESERVATION_TIME
        self.kill_desktop = kill_desktop
        self.require_keep_reservation = require_keep_reservation

    def reserve_ue(self, ue_sn):
        """
        Reserve UE.
        :param ue_sn:
        """
        self.logger.debug("Backend type:{}".format(type(self._backend)))
        # if not self._backend.is_ue_sn_available(ue_sn):
        #     raise UeSerialNumberUnavailableException(str(ue_sn))
        with self._ues_locks.ue_lock(ue_sn):
            self.logger.info("Reserve UE: {}".format(ue_sn))
            ue = self._ues_reserved.get(ue_sn, None)
            self.logger.debug('Current UE object: {}'.format(ue))
            if ue is None:
                self._cleanup_backend(ue_sn)
                self._ues_reserved[ue_sn] = self._backend.reserve_ue(ue_sn)
                self._take_care_thread.add_careable(ue_sn, self._ues_reserved[ue_sn])
                return

            if ue_sn not in self._take_care_thread.to_care:
                self._ues_reserved[ue_sn] = self._backend.cleanup_ue(ue_sn, ue)
                self._take_care_thread.add_careable(ue_sn, ue)
                return

            if self._is_reservation_out_of_date(ue_sn):
                self._ues_reserved[ue_sn] = self._backend.cleanup_ue(ue_sn, ue)
                return
            raise UeAleadyReservedException(ue_sn)

    def get_ue(self, ue_sn):
        """
        :param ue_sn:
        :return:
        """
        #
        # ue = self._ues_locks.run_if_ue_unlocked(ue_sn, inner_get_ue, None)
        if self._ues_locks.ue_lock(ue_sn).locked():
            raise UeNotReservedException("UE {} is now being reserving or unreserving so now you can not access it".format(ue_sn))
        self._ensure_reserved(ue_sn)
        self._raise_if_out_of_date(ue_sn)
        return self._ues_reserved[ue_sn]

    def _raise_if_out_of_date(self, ue_sn):
        if not self.require_keep_reservation:
            return
        if self._is_reservation_out_of_date(ue_sn):
            raise UeReservationOutOfDate(ue_sn, time.time() - self._ues_reserved_times[ue_sn])

    def _ensure_reserved(self, ue_sn):
        if not self.require_keep_reservation:
            return
        if ue_sn not in self._ues_reserved:
            raise UeNotReservedException(ue_sn)

    def _cleanup_backend(self, ue_sn):
        self._backend.backend_that_created_ues.pop(ue_sn, None)

    def unreserve_ue(self, ue_sn, raise_if_out_of_date=True):
        """
        :param ue_sn:
        :param raise_if_out_of_date:
        """
        if ue_sn not in self._ues_reserved:
            self.logger.warning('UE: {} was already unreserved'.format(ue_sn))
            return
        self.logger.info("Unreserve UE: {}".format(ue_sn))
        with self._ues_locks.ue_lock(ue_sn):
            self.logger.debug("Unreserve UE: {} processing".format(ue_sn))
            if raise_if_out_of_date:
                self._raise_if_out_of_date(ue_sn)
            ue = self._ues_reserved[ue_sn]
            self._take_care_thread.remove_careable(ue_sn)
            self._backend.unreserve_ue(ue_sn, ue)
            with self._ues_keep_locks.ue_lock(ue_sn):
                self.logger.debug("Deleting {} from reservation list".format(ue_sn))
                self._ues_reserved_times.pop(ue_sn, None)
                self._ues_reserved.pop(ue_sn, None)
            self.logger.info("Unreserve UE: {} finish".format(ue_sn))

    def keep_reservation(self, ue_sn):
        """
        :param ue_sn:
        :return:
        """
        # self.logger.info("start keep reservation for UE {}".format(ue_sn))
        if self._ues_locks.ue_lock(ue_sn).locked():
            self.logger.info("UE is locked, can not keep reservation {}".format(ue_sn))
            return
        with self._ues_keep_locks.ue_lock(ue_sn):
            self._keep_reservation_core(ue_sn)
        # self.logger.info("finish success keep reservation for UE {}".format(ue_sn))

    def _keep_reservation_core(self, ue_sn):
        last_timestr = time.strftime("%Y-%m-%d--%H-%M-%S", time.gmtime(self._ues_reserved_times.get(ue_sn, time.time())))
        self._ues_reserved_times[ue_sn] = time.time()
        timestr = time.strftime("%Y-%m-%d--%H-%M-%S", time.gmtime(self._ues_reserved_times[ue_sn]))
        self.logger.debug("UE reservation time updated for UE '{}' from time {} to time: {}".format(ue_sn, last_timestr, timestr))

    def _is_reservation_out_of_date(self, ue_sn):
        last_reservation_time = self._ues_reserved_times.get(ue_sn, None)
        if last_reservation_time is None:
            return False
        now = time.time()
        if now - last_reservation_time >= UE_RESERVATION_TIME:
            timestr = time.strftime("%Y-%m-%d--%H-%M-%S", time.gmtime(self._ues_reserved_times[ue_sn]))
            nowstr = time.strftime("%Y-%m-%d--%H-%M-%S", time.gmtime(now))
            self.logger.debug("UE {} is out of date, last update time: {}, now: {}".format(ue_sn, timestr, nowstr))
            return True
        return False

    def take_care(self, ue_sn, ue_control):  # pylint: disable=arguments-differ, unused-argument
        """
        Checks if UE reservation is not updated and unreserve UE in case of.
        :param ue_sn:
        :param ue_control:
        :return:
        """
        self.logger.info("Taking care of ue_pool_on_server. Currently reserved UEs: {}".format(list(self._ues_reserved_times.keys())))
        if self._ues_locks.ue_lock(ue_sn).locked():
            return
        last_reservation_time = self._ues_reserved_times.get(ue_sn, time.time())
        reservation_period = time.time() - last_reservation_time
        if reservation_period > self.reservation_timeout:
            self.logger.info("UE {} reservation was not updated for {}s > {}s. This UE will be unreserved".format(ue_sn, reservation_period,
                                                                                                                  self.reservation_timeout))
            self.unreserve_ue(ue_sn, raise_if_out_of_date=False)

    def report_exception(self, ue_sn, ue_control, exception):  # pylint: disable=arguments-differ, unused-argument
        """

        :param ue_sn:
        :param ue_control:
        :param exception:
        :return:
        """
        trace = traceback.format_exc()
        self.logger.warning("Got Exception inside UePool2WithTakeCareThread unreserving thread {} {}".format(exception, trace))

    def get_ue_type(self, ue_sn):
        """Return UE type"""
        return self._backend.get_ue_type(ue_sn)

    def shutdown(self):
        """
        Releases resources used by this pool.
        For examples, kills all threads.
        """
        self._take_care_thread.clear_and_finish()
        if self._take_care_thread.isAlive():
            self._take_care_thread.join(DEFAULT_FINISH_POOL_TAKE_CARE_THREAD_TIMEOUT)
        for ue_sn in list(self._ues_reserved_times.keys()):
            del self._ues_reserved_times[ue_sn]


